def min_area_rect(points):
    n = len(points)
    best = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):                     # every group of 4 points
                    group = [points[i], points[j], points[k], points[l]]
                    xs = sorted(set(p[0] for p in group))
                    ys = sorted(set(p[1] for p in group))
                    if len(xs) == 2 and len(ys) == 2:
                        corners = {(x, y) for x in xs for y in ys}
                        if corners == set(map(tuple, group)):
                            area = (xs[1] - xs[0]) * (ys[1] - ys[0])
                            best = min(best, area)
    return best if best != float('inf') else 0

