import java.util.*;

public class Main {
    static int minAreaRect(int[][] points) {
        Set<Long> pointSet = new HashSet<>();
        for (int[] pt : points) pointSet.add(encode(pt[0], pt[1]));

        long best = Long.MAX_VALUE;
        int n = points.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int x1 = points[i][0], y1 = points[i][1];
                int x2 = points[j][0], y2 = points[j][1];
                if (x1 == x2 || y1 == y2) continue;             // not a valid diagonal
                if (pointSet.contains(encode(x1, y2)) && pointSet.contains(encode(x2, y1))) {  // O(1) lookups
                    long area = (long) Math.abs(x2 - x1) * Math.abs(y2 - y1);
                    best = Math.min(best, area);
                }
            }
        }
        return best == Long.MAX_VALUE ? 0 : (int) best;
    }

    static long encode(int x, int y) {
        return (long) (x + 50000) * 100000 + (y + 50000);
    }
}

