#include <bits/stdc++.h>
using namespace std;

long long encode(int x, int y) { return (long long)(x + 50000) * 100000 + (y + 50000); }

int minAreaRect(vector<vector<int>>& points) {
    unordered_set<long long> pointSet;
    for (auto& pt : points) pointSet.insert(encode(pt[0], pt[1]));

    long long best = LLONG_MAX;
    int n = points.size();
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int x1 = points[i][0], y1 = points[i][1];
            int x2 = points[j][0], y2 = points[j][1];
            if (x1 == x2 || y1 == y2) continue;                 // not a valid diagonal
            if (pointSet.count(encode(x1, y2)) && pointSet.count(encode(x2, y1))) {  // O(1) lookups
                long long area = abs((long long)x2 - x1) * abs((long long)y2 - y1);
                best = min(best, area);
            }
        }
    }
    return best == LLONG_MAX ? 0 : (int)best;
}
